#!/bin/sh
set -eu

# Lint every shell script in the repo (including git hooks) with ShellCheck.

CDPATH='' cd -P -- "$(dirname -- "$0")/../.."

command -v shellcheck >/dev/null 2>&1 || {
  echo "Error: shellcheck is required (mise install, or brew install shellcheck)." >&2
  exit 1
}

# Tracked and untracked-but-not-ignored scripts; gradlew is generated by Gradle.
. ./scripts/checks/lib/lintFiles.sh
files=$(mktemp)
trap 'rm -f "$files"' EXIT
trap 'exit 1' HUP INT TERM
list_lint_files '*.sh' 'scripts/git/hooks/*' > "$files"
[ ! -s "$files" ] || xargs -0 shellcheck -x < "$files"
